// Import the Verus prelude and the builtin Vec
use verus::prelude::*;
use builtin::vec::Vec;

verus! {

    /// Given a non‐empty input vector of characters whose first character
    /// is in ['a'..='y'], construct a length‐2 vector whose first character
    /// is the successor in the alphabet, and whose second character is '\n'.
    pub fn solve(input: Vec<char>) -> Vec<char>
        requires
            // input is non‐empty
            input.len() > 0,
            // first element ∈ ['a'..='y']
            input.index(0) >= 'a' && input.index(0) <= 'y'
        ensures
            |res: Vec<char>| {
                // result has exactly two characters
                res.len() == 2
                // first character is the successor of input[0]
                && res.index(0)
                    == char::from_u32((input.index(0) as u32) + 1).unwrap()
                // second character is newline
                && res.index(1) == '\n'
            }
    {
        // Read the first character
        let first = input.index(0);

        // Compute its Unicode code point + 1
        let succ_code = (first as u32) + 1;
        // From first ≤ 'y' (code 121), succ_code ≤ 122 = 'z'
        assert(succ_code <= ('z' as u32));
        // Safe to unwrap because succ_code ∈ ['b'..='z']
        let succ_char = char::from_u32(succ_code).unwrap();

        // Build the two‐character result
        let mut res = Vec::new();
        res.push(succ_char);
        res.push('\n');
        res
    }
}